contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 amount) public {
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool reverted;
        bool ok;
        bool r = c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; ok = false; } else { reverted = false; ok = r; }
        uint256 balAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(
            (reverted == (amount > balBefore)) &&
            (reverted || (ok && supplyAfter == supplyBefore && toAfter == toBefore + amount && balAfter + amount == balBefore + amount))
        );
    }
    receive() external payable {}
}

