pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address to, uint256 amount) internal {
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 toBefore;
        try c.balanceOf(to) returns (uint256 __r) { toBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        bool reverted;
        bool ok;
        try c.transfer(to, amount) returns (bool r) { reverted = false; ok = r; }
        catch { reverted = true; ok = false; }
        uint256 balAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 toAfter;
        try c.balanceOf(to) returns (uint256 __r) { toAfter = __r; } catch { return; }
        uint256 supplyAfter;
        try c.totalSupply() returns (uint256 __r) { supplyAfter = __r; } catch { return; }
        assertTrue((reverted == (amount > balBefore)) &&
            (reverted || (ok && supplyAfter == supplyBefore && toAfter == toBefore + amount && balAfter + amount == balBefore + amount)));
    }

    function testFuzz_run(address to, uint256 amount) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, amount);
    }

    receive() external payable {}
}
